#![allow(dead_code)]
use serde_json::{Value,json};
use openvector::document_controls::DocumentSettings;
use openvector::image_document::{ImageDocument,DocumentSnapshot,AutomaticResult};
use openvector::palette::CoreSession;

pub fn hex(value:&str)->Vec<u8>{assert_eq!(value.len()%2,0);value.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
pub fn clean_startup_profile()->Value{json!({"category":-1,"quality":1,"sensitivity":1,"advanced":false,"antiAlias":true,"complexity":5,"minimumPixels":0,"artifactRejection":0,"clusterColors":true,"smoothness":6,"detectCorners":true,"curveComplexity":6,"smoothingAntiAlias":true,"paletteMode":1,"palette":[],"backgroundMode":-1,"background":[0,0,0,1]})}
pub fn automatic_document(input:&Value)->(ImageDocument,AutomaticResult){
    let decoded=openvector::image_input::decode_image(&crate::common::b64(input["bytes"].as_str().unwrap())).unwrap();let filename=openvector::image_input::resolve_image_filename(input["name"].as_str().unwrap());let mut document=CoreSession::default().create_document();
    document.set_source(decoded.width,decoded.height,&decoded.bgra,decoded.has_alpha,filename.shadow_control as f64).unwrap();let mut controls=clean_startup_profile();controls["extension"]=json!(filename.extension);let automatic=document.run_automatic(&controls).unwrap();(document,automatic)
}
/// Ignore serde's integer/float storage distinction, but retain signed-zero
/// identity. Object membership and array sizes remain exact; no keys are dropped.
pub fn compare_json(actual:&Value,expected:&Value,label:&str){
    match(actual,expected){
        (Value::Number(a),Value::Number(b))=>assert_eq!(a.as_f64().unwrap().to_bits(),b.as_f64().unwrap().to_bits(),"{label}: {a} versus {b}"),
        (Value::Array(a),Value::Array(b))=>{assert_eq!(a.len(),b.len(),"{label} length");for(i,(a,b))in a.iter().zip(b).enumerate(){compare_json(a,b,&format!("{label}[{i}]"));}},
        (Value::Object(a),Value::Object(b))=>{assert_eq!(a.len(),b.len(),"{label} key count");for(key,b)in b{compare_json(a.get(key).unwrap_or_else(||panic!("{label} missing {key}")),b,&format!("{label}.{key}"));}},
        _=>assert_eq!(actual,expected,"{label}")
    }
}
pub fn compare_settings(settings:&DocumentSettings,bits:&str,palette_bits:&str){
    let encoded=hex(bits);let i32_at=|offset|i32::from_le_bytes(encoded[offset..offset+4].try_into().unwrap());let f32_at=|offset|f32::from_le_bytes(encoded[offset..offset+4].try_into().unwrap());
    for(name,actual,offset)in [("category",settings.category,0),("quality",settings.quality,4),("sensitivity",settings.sensitivity,12),("backgroundMode",settings.background_mode,68),("complexity",settings.complexity,20),("minimumPixels",settings.minimum_pixels,24),("artifactRejection",settings.artifact_rejection,28),("smoothness",settings.smoothness,36),("curveComplexity",settings.curve_complexity,44),("paletteMode",settings.palette_mode,60)]{assert_eq!(actual,i32_at(offset),"settings {name}");}
    for(name,actual,offset)in [("advanced",settings.advanced,52),("antiAlias",settings.anti_alias,16),("clusterColors",settings.cluster_colors,32),("detectCorners",settings.detect_corners,40),("smoothingAntiAlias",settings.smoothing_anti_alias,48)]{assert_eq!(actual,i32_at(offset)!=0,"settings {name}");}
    for(channel,offset)in [84,80,76,72].into_iter().enumerate(){assert_eq!(settings.background[channel].to_bits(),f32_at(offset).to_bits(),"background channel {channel}");}
    let palette=hex(palette_bits);assert_eq!(settings.palette.len()*4,palette.len());for(index,&value)in settings.palette.iter().enumerate(){let offset=(index/4*4+3-index%4)*4;assert_eq!(value.to_le_bytes(),palette[offset..offset+4],"committed palette {index}");}
}
fn float_value(value:f64)->Value{if value.is_finite(){json!(value)}else{json!({"float64Bits":value.to_le_bytes().iter().map(|b|format!("{b:02x}")).collect::<String>()})}}
fn contours_value(state:&DocumentSnapshot)->Value{match &state.contours{None=>Value::Null,Some(geometry)=>{let mut out=geometry.to_json();for(i,node)in geometry.nodes.iter().enumerate(){out["nodes"][i]["x"]=float_value(node.x);out["nodes"][i]["y"]=float_value(node.y);}out}}}
fn fitted_value(state:&DocumentSnapshot)->Value{match &state.fitting{None=>Value::Null,Some(fitting)=>{let mut out=fitting.geometry.to_json();for(i,node)in fitting.geometry.nodes.iter().enumerate(){out["nodes"][i]["x"]=float_value(node.x);out["nodes"][i]["y"]=float_value(node.y);}for(i,cubic)in fitting.geometry.cubics.iter().enumerate(){for(c,&v)in cubic.points.iter().enumerate(){out["cubics"][i]["points"][c]=float_value(v);}}out}}}
pub fn compare_document_state(state:&DocumentSnapshot,expected:&Value,parameters:&Value){assert_eq!(state.progress as i64,expected["progress"].as_i64().unwrap(),"completion progress");compare_document_computation(state,expected,parameters);}
pub fn compare_document_computation(state:&DocumentSnapshot,expected:&Value,parameters:&Value){
    compare_settings(&state.settings,expected["settingsBits"].as_str().unwrap(),expected["committedPaletteArgbBits"].as_str().unwrap());
    assert_eq!(state.status as u64,expected["status"].as_u64().unwrap());assert_eq!(state.cancelled,expected["cancelled"].as_bool().unwrap());assert_eq!(state.processed,expected["processed"].as_bool().unwrap());assert_eq!(state.random_state as u64,expected["randomState"].as_u64().unwrap());
    // Serialize only compared fields. A full snapshot also expands three BGRA
    // buffers into JSON arrays, while the pixel checks below use their raw bytes.
    assert_eq!(state.stage_keys.palette,expected["cacheKey"].as_str().unwrap());let stage_keys=json!({"palette":state.stage_keys.palette,"reservedC0":state.stage_keys.reserved_c0,"segmentation":state.stage_keys.segmentation,"segmentationEdits":state.stage_keys.segmentation_edits,"smoothing":state.stage_keys.smoothing,"fitting":state.stage_keys.fitting});for(key,value)in expected["stageKeys"].as_object().unwrap(){compare_json(&stage_keys[key],value,&format!("stage key {key}"));}
    compare_json(&json!(state.completed),&expected["completed"],"completed candidates");let scores:Vec<u8>=state.scores.iter().flat_map(|v|v.to_le_bytes()).collect();assert_eq!(scores,hex(expected["scoreBits"].as_str().unwrap()),"score bits");
    assert_eq!(state.palettes.len(),25);assert_eq!(expected["paletteBits"].as_array().unwrap().len(),25);for(count,palette)in state.palettes.iter().enumerate(){let bits:Vec<u8>=palette.iter().flat_map(|v|v.to_le_bytes()).collect();assert_eq!(bits,hex(expected["paletteBits"][count].as_str().unwrap()),"palette {count} bits");}
    for(kind,image)in [("source",&state.source),("working",&state.working)]{compare_json(&json!([image.width,image.height]),&expected[format!("{kind}Dimensions")],&format!("{kind} dimensions"));assert_eq!(image.bgra,crate::common::b64(expected[format!("{kind}Bgra")].as_str().unwrap()),"{kind} pixels");}
    let shared=hex(expected["sharedBits"].as_str().unwrap());let actual=[state.parameters["usePalette"].as_bool().unwrap() as u32,state.parameters["Shared::is_anti_aliased"].as_f64().unwrap() as u32,0,state.parameters["shadowing"].as_bool().unwrap() as u32,state.parameters["clusterColors"].as_bool().unwrap() as u32,state.parameters["Shared::image_type_code"].as_f64().unwrap() as u32];assert_eq!(actual.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>(),shared,"shared controls");
    let mut palette_controls=Vec::new();palette_controls.extend_from_slice(&(state.parameters["PaletteFinder::cost_per_color"].as_f64().unwrap() as f32).to_le_bytes());for key in ["PaletteFinder::use_16_hist_bins","PaletteFinder::use_26_connected_peaks"]{palette_controls.extend_from_slice(&(state.parameters[key].as_f64().unwrap() as i32).to_le_bytes());}assert_eq!(palette_controls,hex(expected["paletteControlBits"].as_str().unwrap()),"palette controls");
    for(name,descriptor)in parameters.as_object().unwrap(){let value=&state.parameters[name];let values:Vec<&Value>=if let Some(a)=value.as_array(){a.iter().collect()}else{vec![value]};assert_eq!(values.len(),descriptor["count"].as_u64().unwrap() as usize,"{name} count");let mut encoded=Vec::new();for value in values{let number=value.as_f64().unwrap();match descriptor["kind"].as_str().unwrap(){"float64"=>encoded.extend_from_slice(&number.to_le_bytes()),"float32"=>encoded.extend_from_slice(&(number as f32).to_le_bytes()),_=>encoded.extend_from_slice(&(number as i32).to_le_bytes())}}assert_eq!(encoded,hex(expected["parameterBits"][name].as_str().unwrap()),"{name} bits");}
    if expected["segmentation"]["width"]==0&&expected["segmentation"]["height"]==0{assert!(state.segmentation.is_none());compare_json(&expected["segmentation"],&json!({"width":0,"height":0,"indices":[],"counts":[],"colorIndices":[],"palette":[]}),"empty segmentation");}else{let segmentation=state.segmentation.as_ref().map(|m|json!({"width":m.width,"height":m.height,"indices":m.indices,"palette":m.palette,"counts":m.counts,"colorIndices":m.color_indices}));compare_json(&segmentation.unwrap_or(Value::Null),&expected["segmentation"],"segmentation");}
    compare_json(&contours_value(state),&expected["contours"],"complete contours");
    if expected["smoothingMetadata"].is_null(){assert!(state.smoothing.is_none());}else{let smoothing=state.smoothing.as_ref().unwrap();let e=&expected["smoothingMetadata"];compare_json(&json!(smoothing.border_counts),&e["borderCounts"],"border counts");compare_json(&json!(smoothing.penalty_counts),&e["penaltyCounts"],"penalty counts");let actual:Vec<u32>=smoothing.reference_positions.iter().map(|v|v.to_bits()).collect();let expected:Vec<u32>=e["referencePositions"].as_array().unwrap().iter().map(|v|(v.as_f64().unwrap() as f32).to_bits()).collect();assert_eq!(actual,expected,"reference position bits");}
    if expected["fittedGeometry"].is_null(){assert!(state.fitting.is_none());}else{compare_json(&fitted_value(state),&expected["fittedGeometry"],"complete fitted geometry");let output_chains=state.fitting.as_ref().and_then(|f|f.output_chains.as_ref()).map(|c|json!({"children":c.children,"holes":c.holes}));compare_json(&output_chains.unwrap_or(Value::Null),&expected["outputChains"],"complete output chains");}
}
